const hintMessages={predict:['Look for the distance at zero seconds, then compare it with the distance at four seconds.','The scene starts at 6 meters remaining and shows 3 meters remaining after four seconds. How much closer is that?'],roles:['Ask what each quantity measures. A starting value is read when x = 0.','6 is initial meters remaining; −3/4 is change per second; x is elapsed seconds; y is meters remaining.'],guided:['In −3/4, the denominator tells the horizontal change; the numerator tells the vertical change.','Start at (0, 9). Move right 4 and down 3 to (4, 6). Continue that pattern until zero meters remain.'],diagnose:['The point (0, 6) already matches the initial value. Check which change belongs to the numerator.','Keep the intercept. Use horizontal 4 and vertical −3, so the slope is −3/4.'],cue:['Arrival time = starting distance ÷ approach speed. Is your current arrival early, late, or exactly six?','One fix keeps 6 meters and uses 1 m/s. Another keeps 0.75 m/s and uses a 4.5-meter start. Match the equation to whichever route you choose.'],independent:['The constant term gives the y-coordinate when x = 0. A positive slope rises as x increases.','Use (0, −2), then rise 2 and run 3 to (3, 0). Both points satisfy y = (2/3)x − 2. The x-intercept is 3.'],transfer:['Read the starting value at x = 0. The arrival occurs when meters remaining reach zero.','Five meters at half a meter per second takes 10 seconds. A finite segment ends at (10, 0).']};
function hint(id){const used=state.supports[id]||[],n=used.includes('hint-1')?1:0;state=addSupport(state,id,'hint-'+(n+1));let texts=hintMessages[id];if(id.startsWith('practice')){const p=practice.find(x=>x.id===id);texts=[`Begin at (0, ${p.b}). Read the sign of the slope to choose the direction.`,`A valid second point is (1, ${p.m+p.b}). ${p.m===0?'This horizontal line has no x-intercept.':`The x-intercept is ${fmt(-p.b/p.m)}.`}`];}hintText[id]=texts[n];save();render(false);}
function practiceComparison(id){const p=practice.find(x=>x.id===id);return `Start at (0, ${p.b}). A different point is (1, ${p.m+p.b}). The line ${p.m>0?'rises':p.m<0?'falls':'stays level'}. ${p.m===0?'There is no x-intercept.':`The x-intercept is (${fmt(-p.b/p.m)}, 0).`}`;}
function supported(id){state=addSupport(state,id,'worked-comparison');const response={...(state.records[id]?.latest.response||draft(id)),supportRoute:'Continue with support',currentDraft:{...draft(id)},originalLatest:state.records[id]?.latest.response||null};record(id,response,{correct:null,ungraded:true,workedComparison:true},{supported:true});const model={predict:'At zero seconds 6 meters remain. After four seconds, 3 meters remain. The distance decreased by 3 meters. The graph next will show arrival at eight seconds.',roles:'6: initial meters remaining. −3/4: change in meters remaining per second. x: elapsed seconds. y: meters remaining.',guided:'Start (0, 9). Right 4, down 3 reaches (4, 6). The useful segment ends at (12, 0), so arrival is 12 seconds.',diagnose:'Exchange the changes. Keep (0, 6), then move right 4 / down 3. The correct graph reaches (8, 0).',cue:'A 6-meter start with 1 m/s approach reaches the target at six seconds. A 4.5-meter start with 0.75 m/s also works. Select the equation for your current route to test again.',independent:'Start (0, −2); rise 2 and run 3 to (3, 0). The line rises and its x-intercept is 3.',transfer:'Start 5 meters away; decrease remaining distance by 1 meter every 2 seconds; arrive at 10 seconds. Use a segment from (0, 5) to (10, 0).'};setFeedback(id,'Worked comparison · support recorded',`<p>${model[id]||hintMessages[id]?.[1]||(id.startsWith('practice')?practiceComparison(id):'Use the intercept and slope to compare your construction with the model.')}</p><p>Your earlier responses remain saved. This supported submission counts toward completion, with support use shown in your evidence.</p>`,false);}
render();
